(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-subject-verb-agreement":{"title":"Subject-Verb Agreement","topic":"Grammar & Usage","questions":[{"id":"grammar-subject-verb-agreement-q0001","version":2,"contentHash":"sha256:597368f75026f0e45bd7c06b9ca817e902cc7aebc1572e1c2448a87aa4d19a54","question":"Which is correct: 'The dog ___ in the yard.'","choices":["bark","barks","barking","barked"],"correct":1,"explanation":{"correct":"Answer: barks. Because 'The dog' is a singular subject, you must add an 's' or 'es' to the verb to show subject-verb agreement in the present tense.","incorrect":[{"choice":"bark","category":"subject-verb disagreement","reason":"The word 'bark' is plural. Since 'the dog' is a single subject, we need the singular verb form 'barks' to make the sentence agree."},"",{"choice":"barking","category":"missing helping verb","reason":"'Barking' is a participle that needs a helping verb like 'is' or 'was' to function as the main verb of a sentence."},{"choice":"barked","category":"incorrect verb tense","reason":"While 'barked' is a valid verb, in this sentence structure, we are describing a habitual action of the dog, so we use the present tense form 'barks'."}]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a singular verb, and a plural subject needs a plural verb.","example":"The cat purrs (correct) vs. The cat purr (incorrect); The cats purr (correct) vs. The cats purrs (incorrect).","strategyClue":"Look at the subject and decide if it is one thing or more than one thing. If there is only one, test the verb by seeing if it sounds right with an 's' at the end.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0002","version":2,"contentHash":"sha256:70a2f5ce58a07802f87c6ca869cde3aecf7361ee2f625bada5d3458d72b1e7b7","question":"Which is correct: 'The dogs ___ in the yard.'","choices":["bark","barks","barking","barked"],"correct":0,"explanation":{"correct":"Answer: bark. Because the subject 'The dogs' is plural, the verb must match it in its base plural form. We use 'bark' for plural subjects.","incorrect":["",{"choice":"barks","category":"subject-verb disagreement","reason":"The verb 'barks' ends in an 's' and is used for singular subjects, like 'the dog.' Since 'The dogs' is plural, 'barks' does not fit."},{"choice":"barking","category":"missing helping verb","reason":"Using 'barking' alone is incomplete. To use this form, you would need a helping verb like 'are' (The dogs are barking)."},{"choice":"barked","category":"incorrect verb tense","reason":"While 'barked' is a valid past tense, it implies the action is finished. In the context of a general statement about the dogs in the yard, the present tense 'bark' is the standard choice."}]},"studyAid":{"definition":"Subjects and verbs must agree in number. A plural subject takes the base form of the verb, while a singular subject usually adds an 's' to the verb.","example":"The dog barks (singular); The dogs bark (plural). The cat purrs; The cats purr.","strategyClue":"Identify the subject and ask yourself: is there more than one? If the subject is plural, look for the version of the verb that does not have an 's' at the end.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0003","version":2,"contentHash":"sha256:08ea2c54a77f9b496ff9d189fd87cb63eb74cd4a5208dbfe64bb8dd2ec46b579","question":"Which is correct: 'She ___ to school every day.'","choices":["walk","walks","walking","walked"],"correct":1,"explanation":{"correct":"Answer: walks. Because the subject 'she' is a singular third-person pronoun, the verb must end in '-s' to show subject-verb agreement in the present tense.","incorrect":[{"choice":"walk","category":"subject-verb disagreement","reason":"The verb 'walk' would be used with 'I', 'you', 'we', or 'they'. Since the subject is 'she', you must use the singular form 'walks'."},"",{"choice":"walking","category":"missing helping verb","reason":"'Walking' is an action that needs a helping verb like 'is' or 'was' to work in this sentence. Without one, it cannot function as the main verb."},{"choice":"walked","category":"incorrect verb tense","reason":"The phrase 'every day' tells us this happens regularly, so we use the present tense. 'Walked' is the past tense and refers to something that already happened."}]},"studyAid":{"definition":"In the present tense, singular subjects (he, she, it) require the verb to end in -s or -es. Plural subjects (I, you, we, they) use the base form of the verb.","example":"He runs vs. They run; She eats vs. We eat.","strategyClue":"Identify the subject of the sentence first. Ask yourself if the subject is singular or plural, then check which verb form matches that specific subject type.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0004","version":2,"contentHash":"sha256:acb6de79ccab8b065d2d01f8af5ebe1f2c3f37a980a5ec0f023d284643e5261f","question":"Which is correct: 'My friends ___ soccer after school.'","choices":["play","plays","playing","played"],"correct":0,"explanation":{"correct":"Answer: play. The subject 'My friends' is plural, so we use the base verb 'play' to match the plural subject.","incorrect":["",{"choice":"plays","category":"subject-verb disagreement","reason":"The verb 'plays' is used for singular subjects like 'he' or 'she'. Since 'friends' is plural, adding an 's' creates an agreement error."},{"choice":"playing","category":"missing helping verb","reason":"The word 'playing' is an action word that needs a helper verb like 'are' to work in this sentence. By itself, it is incomplete."},{"choice":"played","category":"wrong verb tense","reason":"While 'played' is a correct past tense verb, the sentence structure implies a habitual action or a general statement, for which the simple present tense 'play' is the best fit."}]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a verb with an 's' ending, while a plural subject uses the base form of the verb.","example":"He plays (singular); They play (plural); The dog runs (singular); The dogs run (plural).","strategyClue":"Identify if the subject is one person or multiple people. If the subject is plural (more than one), look for the form of the verb that does not have an 's' attached to it.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0005","version":2,"contentHash":"sha256:83954eca1bde3193f73f8f4e2d7204553b8908515ee5d053508c10b1d5089ac7","question":"Which is correct: 'Neither of the boys ___ late.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. When using 'Neither of,' the subject is considered singular because you are referring to one person or the other, not both together. Therefore, it requires the singular verb 'is'.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"Because 'neither' points to only one boy at a time, 'are' is incorrect as it is a plural verb. The subject 'neither' is singular."},"",{"choice":"were","category":"subject-verb disagreement","reason":"'Were' is a plural past-tense verb. Since 'neither' treats the group as separate individuals, you must use a singular verb form."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is not the correct form to use here. You need a conjugated verb that agrees with the singular subject 'neither'."}]},"studyAid":{"definition":"Words like 'each,' 'either,' and 'neither' are singular, so they always take a singular verb even when followed by a plural noun.","example":"Neither of the dogs is barking. Either of the girls is going. Each of the boys is ready.","strategyClue":"Cover up the phrase 'of the boys' with your finger. Look at the word 'Neither' that remains and ask yourself if it represents a single person or a whole group, then choose the verb that matches that single person.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0006","version":2,"contentHash":"sha256:2ee14aa1555a85f54e987e39b6ca1febc41df4c2de18db6024c8a142481df410","question":"Which is correct: 'The team ___ ready to play.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. 'The team' is a singular collective noun representing one group, so it requires the singular verb 'is'.","incorrect":[{"choice":"are","category":"subject-verb agreement","reason":"'Are' is used for plural subjects. Since 'The team' acts as a single unit, use the singular verb 'is' instead."},"",{"choice":"were","category":"plural past tense","reason":"'Were' is plural and suggests the past. Because the sentence describes a current state, it doesn't match the singular subject 'The team'."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form and does not agree with the subject 'The team'. In this sentence, we need a conjugated present tense verb."}]},"studyAid":{"definition":"A collective noun names a group (like team, class, or family). Treat these as singular when the group acts together as one unit.","example":"The team is ready. (Correct); The team are ready. (Incorrect); The class is quiet. (Correct).","strategyClue":"Look at the subject and ask yourself, 'Is this one group acting as a single unit?' If the answer is yes, choose the verb form that you would use for 'it'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0007","version":2,"contentHash":"sha256:8d0e4e2fa6514df06491bc894f17943a55b6b30b83b8280e3bea4ee4d6b755b0","question":"Which is correct: 'One of my cats ___ black.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. In the phrase 'one of my cats', the subject is 'one'. Since 'one' is singular, it requires the singular verb 'is'.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"It is tempting to look at 'cats' because it is close to the blank, but 'one' is the true subject. 'One' is singular, so 'are' does not match."},"",{"choice":"were","category":"plural verb form","reason":"'Were' is a plural verb. Because the sentence is about only 'one' cat, you must use a singular verb form instead."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form of the verb. It does not fit here because it does not agree with the singular subject 'one'."}]},"studyAid":{"definition":"When a sentence starts with 'one of the...', the subject is 'one'. Because 'one' is singular, the verb must also be singular.","example":"One of the boys is late. (Correct); One of the dogs are hungry. (Incorrect)","strategyClue":"Ignore the plural noun that follows 'of' and focus only on the word 'one'. Ask yourself, 'Does this verb describe just one thing or many things?'","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0008","version":2,"contentHash":"sha256:7739c6d0dcdd8550d825f2c051e149c950ac228071d4015663ebfc3d9bb6add7","question":"Which is correct: 'The books on the shelf ___ dusty.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. The subject of the sentence is 'books,' which is plural. Therefore, you must use the plural verb 'are' to maintain subject-verb agreement.","incorrect":[{"choice":"is","category":"singular verb","reason":"'Is' is a singular verb used for one item, but the subject 'books' is plural. You need a verb that matches the plural subject."},"",{"choice":"was","category":"singular past tense","reason":"'Was' is also a singular verb. Since 'books' refers to more than one, you cannot use a singular verb here."},{"choice":"be","category":"verb form error","reason":"'Be' is the base form of the verb. In this sentence, you need a conjugated verb that agrees with the plural subject 'books' in the present tense."}]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a singular verb, and a plural subject needs a plural verb.","example":"The dog runs (singular). The dogs run (plural). The cat is here. The cats are here.","strategyClue":"Identify the main noun before the prepositional phrase 'on the shelf.' Ask yourself: is that noun naming one thing or more than one thing?","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0009","version":2,"contentHash":"sha256:23d2052e7c879a9658eb31beec7f821a83ae1d36f2976c7819ed570a2e24728a","question":"Which is correct: 'Everyone ___ excited.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. 'Everyone' is an indefinite pronoun that is grammatically singular. Even though it refers to many people, it requires a singular verb form to maintain proper subject-verb agreement.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"The word 'are' is plural, but the subject 'everyone' acts as a singular group. You should match 'everyone' with a singular verb form like 'is'."},"",{"choice":"were","category":"plural verb form","reason":"'Were' is a plural past-tense verb. Since 'everyone' is treated as a singular subject, this verb form does not match the subject in number."},{"choice":"be","category":"incorrect verb form","reason":"The base form 'be' does not correctly complete this sentence in the present tense. We need a verb that agrees with the singular 'everyone', such as 'is' or 'was'."}]},"studyAid":{"definition":"Indefinite pronouns like 'everyone', 'everybody', 'someone', and 'somebody' are always singular and require a singular verb.","example":"Everyone is here. (Correct) / Everyone are here. (Incorrect) / Someone is at the door. (Correct)","strategyClue":"Test if the word belongs to the group of 'every-' or 'some-' words. If you can replace the subject with 'he', 'she', or 'it', you know to use a singular verb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0010","version":2,"contentHash":"sha256:065105ddba726e3e818115c1d3941dccac978019fecb632a799d43694cd3eb37","question":"Which is correct: 'Neither the teacher nor the students ___ happy.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. When using 'neither...nor', the verb must agree with the noun closest to it. Because 'students' is plural, the verb must also be plural.","incorrect":[{"choice":"is","category":"singular subject-verb agreement","reason":"'Is' is a singular verb, but it must match the noun closest to the blank, which is 'students'. Since 'students' is plural, 'is' does not agree."},"",{"choice":"was","category":"singular past tense","reason":"'Was' is singular and cannot be used with the plural noun 'students'. It does not match the subject closest to the verb."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form of the verb. It does not fit the sentence structure needed here to describe the current state of the teacher and students."}]},"studyAid":{"definition":"When using 'neither...nor' or 'either...or', the verb should always agree with the noun that is closest to it.","example":"Neither the cat nor the dogs are playing. Neither the students nor the teacher is ready.","strategyClue":"Cover up the first part of the sentence up to 'nor' and look only at the noun immediately following 'nor'. Choose the verb form that would correctly match just that one noun.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0011","version":2,"contentHash":"sha256:e4727d106f159b4c89e9e96a3aaea76fc521acce77002fd950452309f2d202a1","question":"Which is correct: 'The news ___ surprising.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. The word 'news' is a singular uncountable noun, so it requires a singular verb. Even though it ends in an 's', it represents one single idea or collection of information.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"Although 'are' is plural, 'news' is treated as singular. You cannot say 'the news are' because 'news' is not a plural noun."},"",{"choice":"were","category":"subject-verb disagreement","reason":"The word 'were' is a plural past-tense verb. Since 'news' is singular, this choice does not agree with the subject of the sentence."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form of the verb. It needs to be conjugated to match the subject 'news' in the present tense to make the sentence grammatically complete."}]},"studyAid":{"definition":"Some nouns, like 'news,' 'math,' or 'physics,' end in an 's' but are treated as singular. These words always take singular verbs like 'is' or 'was'.","example":"The news is good (correct), The news are good (incorrect); Math is fun (correct), Math are fun (incorrect).","strategyClue":"Test the noun by replacing it with a pronoun. If you can replace the subject with 'it' instead of 'they', the subject is singular and needs a singular verb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0012","version":2,"contentHash":"sha256:10cfdfc559447d6b26f8fa8ea78506aaaf0a90b6bad039bb1df17da75c9fdcd4","question":"Which is correct: 'Measles ___ a contagious disease.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. Even though 'measles' ends in an 's', it is a singular noun that names one specific disease. It requires a singular verb like 'is'.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"Although 'are' is plural and 'measles' ends with an 's', you should not be fooled by the spelling. Measles is a singular illness, so it needs a singular verb."},"",{"choice":"were","category":"past tense plural","reason":"This verb is plural, which does not match the singular noun 'measles'. Additionally, the sentence describes a general fact, so present tense is required."},{"choice":"be","category":"incorrect verb form","reason":"The base form 'be' does not work here. You need a conjugated verb that agrees with a singular subject to complete the sentence correctly."}]},"studyAid":{"definition":"Some nouns, like names of diseases or subjects (e.g., measles, physics), end in 's' but are actually singular. They always take a singular verb.","example":"Measles is catching. Physics is my favorite subject. (Incorrect: Measles are catching. Physics are my favorite subject.)","strategyClue":"Try replacing the word 'measles' with the pronoun 'it'. If 'it' makes sense in the sentence, you know to use the singular verb form.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0013","version":2,"contentHash":"sha256:0bcf785ca3960bcd95a88e201bc37b4124b681d34f8b950d46d2393757d013fb","question":"Which is correct: 'A number of students ___ absent.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. The phrase 'a number of' acts as a plural quantifier, meaning it describes many individuals. Therefore, it requires a plural verb to agree with the subject 'students'.","incorrect":[{"choice":"is","category":"subject-verb disagreement","reason":"Because the phrase 'a number of' refers to many students, the verb must be plural. 'Is' is a singular verb, which does not match the plural meaning of the subject."},"",{"choice":"was","category":"past singular verb error","reason":"Similar to 'is', the word 'was' is a singular verb. Since 'students' is a plural noun, we need a plural verb form to maintain agreement."},{"choice":"be","category":"incorrect verb form","reason":"The word 'be' is the base form of the verb. In this sentence, we need a conjugated verb that shows the present tense and matches the plural subject."}]},"studyAid":{"definition":"The phrase 'a number of' is treated as a plural subject, while the phrase 'the number of' is treated as a singular subject.","example":"A number of dogs are barking. The number of dogs is five.","strategyClue":"Look at the phrase preceding the noun 'students'. Determine if the phrase represents a collective group of many individuals or a single specific quantity.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0014","version":2,"contentHash":"sha256:8c66ad9becfaa6a79067138351ecd7549c2fca09993e1bad9edc12518a6751a3","question":"Which is correct: 'The number of absent students ___ growing.'","choices":["are","is","were","be"],"correct":1,"explanation":{"correct":"Answer: is. The subject of this sentence is 'number', which is singular. Therefore, the verb must also be singular ('is') to agree with 'number' rather than the plural noun 'students'.","incorrect":[{"choice":"are","category":"subject-verb disagreement","reason":"It is easy to get distracted by the word 'students', but 'number' is the true subject. Since 'number' is singular, we must use 'is' instead of 'are'."},"",{"choice":"were","category":"plural past tense","reason":"The word 'were' is a plural verb. Because the subject 'number' is singular, 'were' does not match the subject of the sentence."},{"choice":"be","category":"base verb error","reason":"'Be' is the base form of the verb. In this sentence, we need a form of the verb that matches the singular subject 'number' in the present tense."}]},"studyAid":{"definition":"The verb must agree with the simple subject, even if other words come between them. If the subject is singular, the verb must be singular.","example":"The pack of wolves is howling. (Correct) vs. The pack of wolves are howling. (Incorrect)","strategyClue":"Cross out the prepositional phrase that starts with 'of' to find the true subject. Look at the word left behind and decide if it is singular or plural to choose your verb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0015","version":2,"contentHash":"sha256:29303401661f0536fbf7aac2e9b1b56d443c723e57818d841cd98a0de3460307","question":"Which is correct: 'Both of the dogs ___ friendly.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. The subject 'Both of the dogs' is plural because it refers to two or more dogs. Therefore, you must use the plural verb form 'are' to match the subject.","incorrect":[{"choice":"is","category":"subject-verb disagreement","reason":"The word 'is' is a singular verb used for one person or thing. Since 'dogs' is plural, you need a verb that matches more than one."},"",{"choice":"was","category":"past tense singular","reason":"The verb 'was' is singular and past tense. It does not fit here because we are talking about two dogs in the present tense."},{"choice":"be","category":"incorrect verb form","reason":"The verb 'be' is the base form and does not correctly complete this sentence in the present tense. We need a conjugated verb that matches the plural subject."}]},"studyAid":{"definition":"Subject-verb agreement means that the verb must match the number of the subject. Use plural verbs for plural subjects (two or more) and singular verbs for singular subjects (one).","example":"The dog is happy. The dogs are happy. Both are hungry.","strategyClue":"Identify the subject of the sentence and ask yourself if it represents one item or multiple items before choosing the matching verb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0016","version":2,"contentHash":"sha256:40e9f8104146e17ecb405f0981d36e557b7c22ff006aebb9f8d69b40a7ed6510","question":"Which is correct: 'Each of the girls ___ a ribbon.'","choices":["have","has","had","having"],"correct":1,"explanation":{"correct":"Answer: has. The subject of the sentence is 'Each,' which is a singular pronoun. Therefore, it requires the singular verb 'has' to maintain subject-verb agreement.","incorrect":[{"choice":"have","category":"subject-verb disagreement","reason":"Because the sentence starts with 'Each,' the subject is singular. 'Have' is a plural verb, so it does not match the singular subject 'Each'."},"",{"choice":"had","category":"incorrect verb tense","reason":"While 'had' is technically a form of the verb, in a simple present tense context describing a general state or belonging, 'has' is the appropriate singular form."},{"choice":"having","category":"missing helping verb","reason":"'Having' is a participle that needs a helping verb like 'is' or 'are' to work in a sentence. On its own, it cannot function as the main verb here."}]},"studyAid":{"definition":"Indefinite pronouns like 'each', 'everyone', and 'everybody' are always singular and must be paired with singular verbs.","example":"Each of the boys has a book. Everyone in the room is quiet. Every student has a pencil.","strategyClue":"Cover up the prepositional phrase 'of the girls' to reveal the true subject. Once you see the word 'Each' standing alone, ask yourself if it represents one person or many.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":16,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0017","version":2,"contentHash":"sha256:98abd9e9763c84e591b42e8d04ef8c50a90412e3ac94028cc876525bae555fbb","question":"I will ___ the sidewalk to the pool.","choices":["followed","follows","follow","following"],"correct":2,"explanation":{"correct":"Answer: follow. Because the sentence begins with 'I will,' we use the base form of the verb. 'Will' is a helping verb that shows the future, and it must always be paired with the simple form of the action verb.","incorrect":[{"choice":"followed","category":"past tense error","reason":"The word 'followed' is in the past tense. Since 'will' points to the future, you should not use the 'ed' ending here."},{"choice":"follows","category":"incorrect verb ending","reason":"The 's' ending is used for present tense with singular subjects like 'he' or 'she'. It does not fit when you use the helping verb 'will'."},"",{"choice":"following","category":"incorrect verb form","reason":"The 'ing' form requires an additional helping verb like 'am,' 'is,' or 'are' (e.g., 'I am following'). It cannot stand alone immediately after 'will'."}]},"studyAid":{"definition":"When you use a future-tense helping verb like 'will,' you must use the base or simplest form of the action word.","example":"Correct: I will run, He will jump. Incorrect: I will ran, He will jumps.","strategyClue":"Look at the helping verb 'will' in the sentence. Ask yourself: 'If I remove the helping verb, which version of the action word sounds most natural on its own?'","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":17,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0018","version":2,"contentHash":"sha256:5107a83f45e838619798a96ef52bec27133c273bb481fe1df013b07d2545c986","question":"Joe and ___ have been friends since kindergarten.","choices":["I","us","we","they"],"correct":0,"explanation":{"correct":"Answer: I. When you are the subject of a sentence, you must use the subject pronoun 'I' rather than the object pronoun 'me' or 'us'.","incorrect":["",{"choice":"us","category":"subject-object pronoun confusion","reason":"The word 'us' is an object pronoun. Because the speaker is part of the subject performing the action of being friends, 'I' is the correct pronoun to use here."},{"choice":"we","category":"pronoun case error","reason":"'We' is a plural subject pronoun. Since 'Joe' is already named as the first part of the subject, adding 'we' creates a redundant subject error."},{"choice":"they","category":"pronoun agreement error","reason":"'They' refers to other people being talked about, not the speaker. If you want to include yourself in the subject, you must use 'I'."}]},"studyAid":{"definition":"Use subject pronouns like 'I', 'he', 'she', and 'they' when the person is performing the action. Use object pronouns like 'me', 'him', 'her', and 'us' when the action is being done to them.","example":"He and I went to the store. (Correct) / Him and me went to the store. (Incorrect)","strategyClue":"Remove 'Joe and' from the sentence and see if the remaining pronoun makes sense on its own. If the sentence works with just the single pronoun as the subject, you have selected the correct form.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":18,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0019","version":2,"contentHash":"sha256:7d512f9e9a197b1c433401de1b22da6ae4ee9b09a75d98b019a2adc1f605e194","question":"Do you ___ how to write in cursive?","choices":["know","knows","now","knew"],"correct":0,"explanation":{"correct":"Answer: know. The subject of the sentence is 'you', so the verb must follow the base form rule for second-person pronouns. 'Know' is the correct present-tense verb to use with 'you'.","incorrect":["",{"choice":"knows","category":"subject-verb disagreement","reason":"The verb 'knows' is only used with third-person singular subjects like 'he', 'she', or 'it'. Since our subject is 'you', we must use the base form 'know'."},{"choice":"now","category":"confused homophone","reason":"'Now' is an adverb used to describe time, meaning 'at this present moment.' It is not a verb, so it cannot be used here to describe the action of understanding."},{"choice":"knew","category":"incorrect verb tense","reason":"'Knew' is the past tense of 'know'. Because this question is asking about a current ability, we should use the present tense 'know' instead."}]},"studyAid":{"definition":"The base form of a verb is used with 'I', 'you', 'we', and 'they'. We add an 's' to the verb only when the subject is 'he', 'she', or 'it'.","example":"I know the answer. She knows the answer. You know how to play. He knows how to play.","strategyClue":"Identify the subject at the start of the sentence, then determine if it represents one person (third person) or if it is 'I' or 'you'. Test the verb by replacing the subject with 'he' to see if the ending needs to change.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":19,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0020","version":2,"contentHash":"sha256:98f8c2b46beaee708a86825d9190db9ca34949b426c2c0e26a3e50593f0c38d0","question":"Mrs. Payne, our principal, ___ us the school song.","choices":["learned","learn","taught","teached"],"correct":2,"explanation":{"correct":"Answer: taught. The word 'taught' is the correct past-tense form of the verb 'teach.' Since Mrs. Payne already performed the action, we must use the irregular past-tense verb.","incorrect":[{"choice":"learned","category":"confused verb meaning","reason":"To 'learn' means to gain knowledge, while to 'teach' means to give knowledge. Since the principal is the one giving the song to the students, 'learned' is the opposite of the intended meaning."},{"choice":"learn","category":"wrong verb tense","reason":"'Learn' is in the present tense, but the sentence describes an action that happened in the past. Additionally, 'learn' implies the principal is receiving information rather than sharing it."},"",{"choice":"teached","category":"incorrect irregular verb","reason":"The word 'teached' is not a real word. 'Teach' is an irregular verb, which means its past tense does not follow the standard '-ed' rule. The correct irregular form is 'taught'."}]},"studyAid":{"definition":"Irregular verbs are special action words that do not add '-ed' to show the past tense; instead, they change their spelling entirely.","example":"teach becomes taught (not teached); buy becomes bought (not buyed); sing becomes sang (not singed).","strategyClue":"Ask yourself if the action happened in the past or is happening now. If it happened in the past, think about whether the verb is a 'rule-follower' that ends in '-ed' or a 'rule-breaker' that changes its shape.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":20,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0021","version":2,"contentHash":"sha256:3cd66cec2a486338916b90bd6d20342719bb096e69c519fb97052b20dddcf4d7","question":"I ___ lived in Ann Arbor, Michigan, for three years.","choices":["has","have","been","be"],"correct":1,"explanation":{"correct":"Answer: have. The subject 'I' is first-person singular, so it requires the verb form 'have' to form the present perfect tense.","incorrect":[{"choice":"has","category":"subject-verb disagreement","reason":"The verb 'has' is used with third-person singular subjects like 'he,' 'she,' or 'it.' For 'I,' we must use 'have.'"},"",{"choice":"been","category":"incorrect verb form","reason":"While 'have been' is a phrase, 'been' by itself cannot follow 'I' to describe a past action in this sentence. The sentence requires a helping verb to show the action."},{"choice":"be","category":"incorrect base form","reason":"The word 'be' is the base form of the verb. It does not fit the structure of the present perfect tense when placed directly after the subject 'I'."}]},"studyAid":{"definition":"Present perfect tense is formed by using 'have' or 'has' followed by the past participle of the main verb to show an action that started in the past and continues to the present.","example":"I have eaten, She has played, We have walked","strategyClue":"Identify the subject of the sentence first. Ask yourself if the subject is singular or plural, then test each option to see which one sounds natural and matches the subject.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":21,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0022","version":2,"contentHash":"sha256:2d138ef13ee622bad68db93cb90d7ca977181890b93a4e64f8c9fcc212c7f790","question":"Will you pass ___ the catsup?","choices":["me","my","we","mine"],"correct":0,"explanation":{"correct":"Answer: me. In this sentence, 'me' is the indirect object receiving the action of the verb 'pass'. We use object pronouns like 'me', 'him', or 'her' after action verbs.","incorrect":["",{"choice":"my","category":"possessive adjective confusion","reason":"'My' is used to show ownership, not to show who is receiving an object. You need a pronoun that acts as the receiver of the action here."},{"choice":"we","category":"subject pronoun usage","reason":"'We' is a subject pronoun, used when someone is performing an action. Since 'you' is the one doing the passing, you need an object pronoun like 'me'."},{"choice":"mine","category":"possessive pronoun error","reason":"'Mine' replaces a noun to show ownership, such as 'that book is mine.' It cannot be used as the object of a verb in this sentence structure."}]},"studyAid":{"definition":"Object pronouns are used to show who or what is receiving the action of a verb, while subject pronouns are used for the person or thing doing the action.","example":"Correct: Pass it to me. Incorrect: Pass it to I. Correct: She helped him. Incorrect: She helped he.","strategyClue":"Test the word by covering the object and saying the sentence aloud. Ask yourself if the word you pick sounds like the person doing the action or the person receiving the action.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":22,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0023","version":3,"contentHash":"sha256:5a2cf2887d0cf4323d88a0ea880e4bfac788cd8c0b0e54818983208591e2444a","question":"The play ___ at 7:15.","choices":["begun","will begin","start","beginned"],"correct":1,"explanation":{"correct":"Answer: will begin. The phrase 'will begin' correctly uses the future tense to indicate that the play is scheduled to happen at a specific time in the future.","incorrect":[{"choice":"begun","category":"past participle error","reason":"'Begun' is the past participle of 'begin' and requires a helping verb like 'has' or 'had'. It cannot stand alone as the main verb of the sentence."},"",{"choice":"start","category":"subject-verb disagreement","reason":"'The play' is a singular subject. To match, the verb must be 'starts'. 'Start' is plural, so it doesn't fit with this singular noun."},{"choice":"beginned","category":"incorrect verb form","reason":"'Beginned' is not a word. The verb 'begin' is irregular, so we use 'began' for the past tense or 'will begin' for the future."}]},"studyAid":{"definition":"Future tense verbs tell us about actions that will happen later. We often use 'will' plus the base form of the verb to show this.","example":"The bus will arrive soon. The store will open at noon.","strategyClue":"Look at the time mentioned in the sentence. If the event is scheduled to happen after now, look for the option that combines a future marker with the correct base verb form.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":23,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0024","version":2,"contentHash":"sha256:4d74e00dc54abcd3897427c5e016ac4b7cca3d494dae19d630b6123cd22e2d59","question":"We ___ our grandmother a can opener.","choices":["gots","gived","bought","buyed"],"correct":2,"explanation":{"correct":"Answer: bought. The verb 'buy' is irregular, meaning it does not follow the standard rule of adding '-ed' to show past tense. The correct past tense form of 'buy' is 'bought'.","incorrect":[{"choice":"gots","category":"incorrect verb form","reason":"The word 'gots' is not standard English. Even if you use 'got' for past tense, it would not fit the intended meaning of purchasing something here."},{"choice":"gived","category":"irregular verb error","reason":"The word 'give' is also an irregular verb. Its past tense form is 'gave', not 'gived'. Adding '-ed' to irregular verbs is a common mistake."},"",{"choice":"buyed","category":"regular verb error","reason":"It is tempting to add '-ed' to the end of a verb to make it past tense, but 'buy' is an irregular verb that changes its spelling to 'bought' instead."}]},"studyAid":{"definition":"Regular verbs show past tense by adding '-ed', but irregular verbs change their spelling in unique ways.","example":"Regular: talk/talked, jump/jumped. Irregular: buy/bought, give/gave, eat/ate.","strategyClue":"Think about whether you have ever heard the word used in real life. If you try to add '-ed' to a verb and it sounds unusual, check if it is an irregular verb that changes spelling instead.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":24,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0025","version":2,"contentHash":"sha256:e960be71088c36c06e9858181ed23c4618f9e6606a476ed95d85b6559454af34","question":"Carol, my friend, ___ German very well.","choices":["speak","speaks","speaked","spoked"],"correct":1,"explanation":{"correct":"Answer: speaks. The subject 'Carol' is singular, so the verb must also be singular. In the present tense, we add an '-s' to the verb when the subject is a singular noun like 'Carol'.","incorrect":[{"choice":"speak","category":"subject-verb disagreement","reason":"The form 'speak' is used for plural subjects (like 'they') or 'I' and 'you'. Since 'Carol' is a single person, we need the singular verb form."},"",{"choice":"speaked","category":"irregular verb error","reason":"'Speaked' is not a real word. The verb 'speak' is irregular, so it does not follow the standard rule of adding '-ed' to show the past tense."},{"choice":"spoked","category":"incorrect verb form","reason":"'Spoked' is incorrect because it is not the past tense of 'speak'. The correct past tense is 'spoke', but since this sentence describes a current ability, we need the present tense form."}]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a singular verb, and a plural subject needs a plural verb.","example":"He runs fast vs. They run fast; She eats cake vs. We eat cake.","strategyClue":"Identify the subject and ask yourself: 'Is it one person or more than one?' If it is one person, choose the verb form that ends in '-s'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":25,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0026","version":2,"contentHash":"sha256:49d1fbf668fd0e0b96b98bafc0369d68fc63d32a95db3c9e9b0d6ee3038c403e","question":"When I was 13, I ___ to Italy with my dad.","choices":["went","goed","was going","had went"],"correct":0,"explanation":{"correct":"Answer: went. The verb 'go' is irregular, so its past tense form is 'went'.","incorrect":["",{"choice":"goed","category":"irregular verb error","reason":"The verb 'go' does not follow the regular pattern of adding '-ed'. It is an irregular verb that changes to 'went' in the past tense."},{"choice":"was going","category":"tense consistency","reason":"While 'was going' is a past tense, it describes an action in progress. 'Went' is the simple past tense needed to describe a completed action that happened at a specific time in the past."},{"choice":"had went","category":"past participle error","reason":"The past participle of 'go' is 'gone'. If you use 'had', you must say 'had gone'. 'Had went' is incorrect because it combines a helper verb with the simple past form."}]},"studyAid":{"definition":"Irregular verbs are verbs that do not follow the standard rule of adding '-ed' to show past tense. You must memorize the unique past tense forms for these words.","example":"go -> went (not goed), eat -> ate (not eated), see -> saw (not seed)","strategyClue":"Ask yourself if the action happened once at a specific moment in the past. If it is a single completed event, look for the simple past form of the irregular verb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":26,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0027","version":2,"contentHash":"sha256:b11ba8bebb24397dda82f0d87d365e3dd21e219ea499d398ee9ef96980c955e2","question":"We will have to wait and let them do ___ job.","choices":["their","they're","there","toward"],"correct":0,"explanation":{"correct":"Answer: their. 'Their' is the possessive form of 'they,' meaning the job belongs to them. Since we are talking about a job that belongs to 'them,' we must use the possessive pronoun.","incorrect":["",{"choice":"they're","category":"homophone confusion","reason":"'They're' is a contraction for 'they are.' If you replace the blank with 'they are,' the sentence reads 'let them do they are job,' which does not make sense."},{"choice":"there","category":"homophone confusion","reason":"'There' refers to a place or a position. Using it here would be incorrect because we are talking about possession, not a location."},{"choice":"toward","category":"wrong part of speech","reason":"'Toward' is a preposition used to show direction. It does not indicate possession and does not fit the grammatical structure required to modify the noun 'job.'"}]},"studyAid":{"definition":"Possessive pronouns show ownership. 'Their' shows that something belongs to a group of people.","example":"Correct: It is their ball. Incorrect: It is they're ball. Correct: They finished their homework.","strategyClue":"Test the word by replacing it with a name, like 'the boys.' If the sentence makes sense as 'the boys' job,' you need the possessive word.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":27,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0028","version":2,"contentHash":"sha256:d2141e3bfff3460b214eed134af2c1b3fd7f53a733c22b652f2792dc2c888cf2","question":"Nathan and Tyler ___ the song beautifully.","choices":["sang","sing","sings","is singing"],"correct":0,"explanation":{"correct":"Answer: sang. The sentence describes an action that has already finished, so we use the past tense form of the irregular verb 'sing', which is 'sang'.","incorrect":["",{"choice":"sing","category":"present tense usage","reason":"'Sing' is the present tense. Since the sentence implies the action happened in the past, we need the past tense form instead."},{"choice":"sings","category":"subject-verb disagreement","reason":"'Sings' is used for a singular subject, but here we have a plural subject (Nathan and Tyler). Also, it is in the present tense."},{"choice":"is singing","category":"incorrect helping verb","reason":"'Is' is used for singular subjects, but this sentence has two people. Even if it were 'are singing', it describes an action happening right now, not a completed past action."}]},"studyAid":{"definition":"Verbs must change their form to show time. Irregular verbs do not follow the standard '-ed' rule for past tense and must be memorized.","example":"Present: I sing a song. Past: I sang a song yesterday. Present: She swims. Past: She swam.","strategyClue":"Look for time-clues in the sentence or context. If the action is finished, look for the specific past tense word form rather than the 'ing' or 's' forms.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":28,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0029","version":2,"contentHash":"sha256:31f12f36800d67413a76e3bd5e5f347e06c847ffc9711069194e6e08a8238f1d","question":"We ___ the car accident from our window.","choices":["saw","seen","seed","was seeing"],"correct":0,"explanation":{"correct":"Answer: saw. This sentence describes a completed action in the past, so we use the simple past tense form of the verb 'to see'.","incorrect":["",{"choice":"seen","category":"incorrect verb form","reason":"'Seen' is a past participle and cannot stand alone as the main verb. It always needs a helping verb like 'have' or 'had' before it."},{"choice":"seed","category":"spelling error","reason":"'Seed' is a noun referring to a plant part, not a verb. It does not mean the same thing as the past tense of 'see'."},{"choice":"was seeing","category":"incorrect tense usage","reason":"'Was seeing' suggests a long, ongoing action. Since an accident is a quick event, we use the simple past tense 'saw' instead."}]},"studyAid":{"definition":"The simple past tense is used for actions that started and finished in the past. Irregular verbs like 'see' change to 'saw' in this tense.","example":"I see the bird. (Present) -> I saw the bird. (Past). We see the stars. (Present) -> We saw the stars. (Past).","strategyClue":"Think about whether the action happened and finished in the past. If it did, choose the verb form that describes a completed moment rather than an ongoing process or a participle that requires a helper.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":29,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0030","version":2,"contentHash":"sha256:dc81b49f01d055816e53f4fb5b3b786dfa092db9944b4ac93e4011415f6535be","question":"I ___ two friends named Sandy.","choices":["have","gots","has","toward"],"correct":0,"explanation":{"correct":"Answer: have. The subject 'I' is a first-person pronoun. In English, 'I' always pairs with the verb form 'have' rather than 'has'.","incorrect":["",{"choice":"gots","category":"non-standard verb form","reason":"The word 'gots' is not a standard English verb. Always use 'have' or 'has' to show possession instead of this incorrect form."},{"choice":"has","category":"subject-verb disagreement","reason":"The verb 'has' is only used with third-person singular subjects like 'he,' 'she,' or 'it.' For 'I,' we must use 'have.'"},{"choice":"toward","category":"wrong part of speech","reason":"'Toward' is a preposition used to show direction, not an action verb. You need a verb here to describe your relationship with your friends."}]},"studyAid":{"definition":"Subject-verb agreement means matching the verb to the subject. 'I' and 'you' always take 'have', while 'he', 'she', and 'it' take 'has'.","example":"I have a cat. She has a cat. We have cats.","strategyClue":"Identify the subject at the beginning of the sentence and test if it belongs to the 'I/you/we/they' group or the 'he/she/it' group to choose the correct verb ending.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":30,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0031","version":2,"contentHash":"sha256:c8042a972282207b3fd13e15b3ea668825bdf3feab3920b41272193c5730993e","question":"Will you go ___ the bank and cash the check?","choices":["to","too","two","toward"],"correct":0,"explanation":{"correct":"Answer: to. 'To' is a preposition used here to indicate direction or a destination. It shows where you are going.","incorrect":["",{"choice":"too","category":"homophone confusion","reason":"'Too' means 'also' or 'excessively.' Using it here doesn't make sense because you are talking about a destination, not an additional action."},{"choice":"two","category":"number word","reason":"'Two' is a number. Since the sentence asks about a direction, not a quantity of banks, this word is incorrect."},{"choice":"toward","category":"preposition choice","reason":"While 'toward' describes direction, it means 'in the general direction of' rather than arriving at the specific destination of the bank for a direct task."}]},"studyAid":{"definition":"'To' is used to show motion toward a destination or to connect an action to an object. It is one of the most common words in English for showing movement.","example":"I am walking to school. / She ran to the store. / We went to the park.","strategyClue":"Ask yourself if the word refers to a number, a level of 'too much,' or a direction. If it describes moving toward a place, pick the preposition that starts with 't' and has one 'o'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":31,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0032","version":2,"contentHash":"sha256:26b288caac557c731c13f86b53eee19af71802dbca668209e61dc3c6a171d4b7","question":"We need to find ___ orange sweater for the party.","choices":["an","a","the","one"],"correct":0,"explanation":{"correct":"Answer: an. The word 'orange' starts with a vowel sound (/o/), so it requires the article 'an'. We use 'an' before words that begin with a, e, i, o, or u sounds.","incorrect":["",{"choice":"a","category":"indefinite article misuse","reason":"Since 'orange' begins with a vowel sound, 'a' cannot be used. We use 'a' only before words starting with consonant sounds."},{"choice":"the","category":"definite article misuse","reason":"'The' is used for a specific, known object. Since this sentence refers to any orange sweater, we use the indefinite article 'an' instead."},{"choice":"one","category":"noun modifier error","reason":"While 'one' indicates a quantity, the sentence structure requires an indefinite article to introduce the noun phrase properly."}]},"studyAid":{"definition":"Use 'a' before words starting with consonant sounds and 'an' before words starting with vowel sounds.","example":"a hat vs. an orange; a dog vs. an eagle; a yellow shirt vs. an old shirt.","strategyClue":"Listen to the very first sound of the word immediately following the blank. If the word starts with a vowel sound, you must use 'an' instead of 'a'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":32,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0033","version":2,"contentHash":"sha256:f979e97799baa5fb88bb0740f60a9f72908760e132dfb4ab6e2f299361ededda","question":"Her dad is the ___ of all of his brothers.","choices":["shortest","shorter","short","most short"],"correct":0,"explanation":{"correct":"Answer: shortest. When comparing one person to more than two other people (a group), use the superlative form of the adjective by adding '-est'.","incorrect":["",{"choice":"shorter","category":"comparative adjective error","reason":"The word 'shorter' is a comparative adjective used to compare only two people. Since there are multiple brothers, we must use the superlative form."},{"choice":"short","category":"base adjective error","reason":"'Short' is the base form and does not show comparison. Because we are ranking him against all of his brothers, we need the superlative form."},{"choice":"most short","category":"incorrect superlative structure","reason":"For most one-syllable adjectives like 'short', we add '-est' to the end. 'Most' is only used for longer words, such as 'most beautiful' or 'most dangerous'."}]},"studyAid":{"definition":"Use the comparative (-er) to compare two things and the superlative (-est) to compare three or more things.","example":"Tall, taller, tallest; fast, faster, fastest; short, shorter, shortest.","strategyClue":"Count the number of people involved in the comparison. If the sentence mentions a group of three or more, use the form ending in '-est'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":33,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0034","version":2,"contentHash":"sha256:25e397f8d91ed48b51f6ee5045c72e9b26e5a59c6fb940e558a147b9692b030f","question":"Andrew had a ___ time at the birthday party.","choices":["good","well","best","better"],"correct":0,"explanation":{"correct":"Answer: good. 'Good' is an adjective that modifies the noun 'time'. Adjectives are used to describe people, places, or things.","incorrect":["",{"choice":"well","category":"adverb vs adjective","reason":"'Well' is usually an adverb used to describe how an action is performed. Since we are describing the noun 'time', we need the adjective 'good'."},{"choice":"best","category":"superlative adjective error","reason":"'Best' is used to compare three or more things. Because this sentence describes one specific time at a party without comparing it to others, 'good' is the correct choice."},{"choice":"better","category":"comparative adjective error","reason":"'Better' is used to compare two things. Since the sentence is not making a comparison between two different times, use the positive form 'good'."}]},"studyAid":{"definition":"Use the adjective 'good' to describe a noun (a person, place, or thing). Use the adverb 'well' to describe how an action is done.","example":"He is a good cook (describes the person). He cooks well (describes the action of cooking).","strategyClue":"Ask yourself if the word after the blank is a noun or a verb. If you are describing a thing, choose the word that provides a quality or description of that object.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":34,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0035","version":2,"contentHash":"sha256:6d3f162ea25a83bed65c7ef7d25c4aa60effc3faecef88db2fa3cb16abc87c15","question":"The test was hard, but Al thought he'd done ___","choices":["well","good","best","better"],"correct":0,"explanation":{"correct":"Answer: well. 'Well' is an adverb that describes the action of doing something. In this sentence, it tells us how Al completed his work on the test.","incorrect":["",{"choice":"good","category":"adjective vs adverb","reason":"'Good' is an adjective used to describe nouns, like a 'good student.' It cannot be used to describe the action of doing something."},{"choice":"best","category":"superlative adjective","reason":"'Best' is a superlative used to compare three or more things. It does not fit here because the sentence describes only Al's own performance."},{"choice":"better","category":"comparative adjective","reason":"'Better' is used to compare exactly two things. Since the sentence doesn't compare Al to anyone else, this word is not the right choice."}]},"studyAid":{"definition":"Use 'good' as an adjective to describe a person, place, or thing. Use 'well' as an adverb to describe how an action is performed.","example":"He is a good soccer player. He plays soccer well.","strategyClue":"Ask yourself if the word describes a noun or an action. If it describes an action (like 'done'), look for the word that functions as an adverb.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":35,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0036","version":2,"contentHash":"sha256:0de651a2cfdcf4436439b2826406ed9623cb9a018423a2a1ab7ffb034cbabd96","question":"He is ___ a solo in the musical.","choices":["singing","sing","sang","sings"],"correct":0,"explanation":{"correct":"Answer: singing. This sentence requires the present participle 'singing' to complete the progressive verb phrase 'is singing,' which shows an action happening right now.","incorrect":["",{"choice":"sing","category":"base verb form","reason":"The phrase 'is sing' is grammatically incorrect. Use the base form 'sing' only after helping verbs like 'can' or 'will,' not after 'is'."},{"choice":"sang","category":"past tense verb","reason":"The form 'sang' is for simple past actions that already happened. 'Is sang' does not work in English because you cannot combine the linking verb 'is' with a past tense verb."},{"choice":"sings","category":"third-person singular verb","reason":"The form 'sings' is for simple present actions (like 'He sings every day'). Using 'is' requires an -ing word to describe an ongoing action."}]},"studyAid":{"definition":"Progressive tenses use a form of the verb 'to be' (am, is, are) plus a present participle ending in -ing to show ongoing action.","example":"He is jumping. They are eating. She is laughing.","strategyClue":"Look at the helping verb 'is' before the blank. Ask yourself which version of the action word fits when describing something happening at this very moment.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":36,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0037","version":2,"contentHash":"sha256:0a21d213535581ca18f4c9fc724f5bd7efccedab1751b529ec66f2a235ec3c5c","question":"Will you ___ me to the swimming pool?","choices":["take","taken","took","toward"],"correct":0,"explanation":{"correct":"Answer: take. In this sentence, 'will' is a helping verb that must be followed by the base form of the verb to show a future action.","incorrect":["",{"choice":"taken","category":"past participle misuse","reason":"The word 'taken' is a past participle and usually needs a helping verb like 'has' or 'was'. It cannot be used alone after 'will'."},{"choice":"took","category":"past tense verb","reason":"'Took' is the past tense form. When you use 'will' to talk about the future, you must use the base form of the verb instead."},{"choice":"toward","category":"preposition versus verb","reason":"'Toward' is a preposition showing direction, not an action verb. A verb is needed here to tell what you are doing to me."}]},"studyAid":{"definition":"When using 'will' to describe a future action, always use the base form of the verb (the simplest version of the word).","example":"Correct: I will run. Incorrect: I will ran. Correct: She will eat. Incorrect: She will eaten.","strategyClue":"Test each word by putting it into the sentence 'I will ___.' Only the word that describes the action in its simplest, present form will make sense.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":37,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0038","version":2,"contentHash":"sha256:216324fc7d791d3e26adb1b246c1cb5cd4b6d68868b528d7a5b1b73557847df3","question":"The drill ___ an extension cord.","choices":["needs","need","needed","do need"],"correct":0,"explanation":{"correct":"Answer: needs. The subject 'The drill' is singular, so it requires the singular verb form 'needs' to agree in number.","incorrect":["",{"choice":"need","category":"subject-verb disagreement","reason":"'Need' is the plural form of the verb. Since 'The drill' is a singular subject, it needs the 's' on the end of the verb."},{"choice":"needed","category":"incorrect verb tense","reason":"'Needed' is the past tense. Because the sentence is stating a current, ongoing requirement for the drill, the present tense 'needs' is the correct choice."},{"choice":"do need","category":"incorrect verb phrase","reason":"'Do need' is plural. A singular subject like 'drill' would require 'does need' if you want to add emphasis, but 'needs' is the standard present tense form."}]},"studyAid":{"definition":"A singular subject (one person or thing) needs a singular verb, which usually ends in 's'. A plural subject needs a plural verb, which usually does not end in 's'.","example":"The dog barks (singular); The dogs bark (plural). She walks (singular); They walk (plural).","strategyClue":"Look at the subject of the sentence. If you can replace the subject with the pronoun 'it', 'he', or 'she', you should choose the verb option that ends in 's'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":38,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0039","version":2,"contentHash":"sha256:fa6cc1cb9a52c710d467d18c14a5e3c334d1e46674390baece37b729db7d7a6a","question":"___ keys are hanging in the front door.","choices":["The","An","A","Those"],"correct":0,"explanation":{"correct":"Answer: The. The word 'The' is the correct definite article because we are talking about a specific set of keys that belong to the front door, rather than just any random keys.","incorrect":["",{"choice":"An","category":"vowel sound article","reason":"'An' is used before singular nouns that start with a vowel sound. 'Keys' is a plural noun, so it cannot take 'an'."},{"choice":"A","category":"singular count article","reason":"'A' is used before singular nouns. Since 'keys' is plural, 'a' does not fit correctly."},{"choice":"Those","category":"demonstrative pronoun usage","reason":"While 'Those' is grammatically possible in some contexts, 'The' is the most natural choice here to identify the specific keys belonging to the door being discussed."}]},"studyAid":{"definition":"The definite article 'the' is used to talk about specific nouns, while 'a' or 'an' are used for singular, non-specific items.","example":"The dog is barking. (a specific dog); A dog is barking. (any dog); The cookies are gone. (those specific cookies).","strategyClue":"Ask yourself if you are describing any group of items or one specific group that the listener should know about. If you are pointing to a particular set of items, use the definite article.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":39,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0040","version":2,"contentHash":"sha256:c6d045005f89a6e5aa5381e27bd92f589080c7a110661cab7494fc13d0dbf17a","question":"Samuel had ___ eyelash on his cheek.","choices":["an","a","one","the"],"correct":0,"explanation":{"correct":"Answer: an. The word 'eyelash' starts with the vowel sound 'eh'. We use 'an' before words that begin with vowel sounds.","incorrect":["",{"choice":"a","category":"indefinite article error","reason":"Since 'eyelash' begins with a vowel sound, 'a' is incorrect. 'A' should only be used before words that start with a consonant sound."},{"choice":"one","category":"unnecessary quantifier","reason":"'One' is a number, not an article. In this sentence, we need the indefinite article 'an' to show that Samuel had any single eyelash on his cheek, not a specific count of them."},{"choice":"the","category":"definite article error","reason":"Using 'the' suggests a specific eyelash that was already mentioned, but the sentence is about any eyelash found on his cheek. Use 'an' to introduce a singular noun for the first time."}]},"studyAid":{"definition":"Use the article 'a' before words starting with consonant sounds and 'an' before words starting with vowel sounds (a, e, i, o, u).","example":"an elephant, a dog, an igloo, a cat.","strategyClue":"Look at the first letter of the noun following the blank and listen to the sound it makes; if that sound is a vowel, choose the article that ends in the letter 'n'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":40,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0041","version":2,"contentHash":"sha256:bc7f6476f03b8eb82d5c299a880c1c839c53ac7f6bcb469860a9acc18118210d","question":"The ___ book I've ever read is Strider.","choices":["best","better","good","well"],"correct":0,"explanation":{"correct":"Answer: best. When comparing three or more things (or referring to one thing out of all possibilities, as in 'the... I've ever read'), we must use the superlative form 'best'.","incorrect":["",{"choice":"better","category":"comparative adjective error","reason":"The word 'better' is used to compare only two things. Because the sentence refers to the entire group of books read, you need the superlative form instead."},{"choice":"good","category":"base adjective error","reason":"The word 'good' is the base form of the adjective and does not show comparison. It cannot be used after the word 'the' in this specific superlative context."},{"choice":"well","category":"adverb usage error","reason":"The word 'well' is an adverb that describes how an action is performed, but 'book' is a noun that needs an adjective to describe it. Even if used as an adjective, it does not fit the comparison rule here."}]},"studyAid":{"definition":"Use the comparative form (-er or 'more') to compare two things, and the superlative form (-est or 'most') to compare three or more things.","example":"This book is better than that one. This is the best book of all time.","strategyClue":"Look at the scope of the comparison: if the sentence implies a group or a total lifetime of experiences, choose the form that signifies the absolute top of the list.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":41,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0042","version":2,"contentHash":"sha256:72f13349710dc2234ebde316a8d9a9698cbe523d7f2c0b2e029aa1da48e1604b","question":"The plane will be landing within the ___.","choices":["hour","our","are","had"],"correct":0,"explanation":{"correct":"Answer: hour. The word 'hour' is a noun that means a period of sixty minutes. In this sentence, it correctly completes the phrase 'within the hour' to indicate a time frame.","incorrect":["",{"choice":"our","category":"possessive pronoun confusion","reason":"'Our' is a word that shows possession (like 'our car'), not a period of time. Using it here makes the sentence have no noun for the plane to land within."},{"choice":"are","category":"verb misuse","reason":"'Are' is a verb used to describe states of being or actions. Putting a verb here results in a sentence fragment because the sentence still lacks a noun."},{"choice":"had","category":"verb misuse","reason":"'Had' is the past tense of 'have.' Since 'within' needs a noun to follow it, 'had' does not fit grammatically in this position."}]},"studyAid":{"definition":"Words that sound the same but have different meanings and spellings are called homophones. 'Hour' refers to time, while 'our' refers to a group that includes yourself.","example":"An hour passed. / This is our house. / They are happy.","strategyClue":"Test if the word is a thing or a measurement of time by replacing the blank with a clear time word like 'minute' or 'day'. Then, check the dictionary definition of your choice to ensure it represents a duration of time.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":42,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0043","version":2,"contentHash":"sha256:3d18121493c363726ea112a69e514ca043f2f015310f5f8b6b052ca877681133","question":"___ baby-sitting for my niece tonight.","choices":["They're","Their","There","They"],"correct":0,"explanation":{"correct":"Answer: They're. This is a contraction that stands for 'they are.' In this sentence, we need a subject and a verb to describe the action, so 'They're baby-sitting' is the correct choice.","incorrect":["",{"choice":"Their","category":"possessive pronoun error","reason":"The word 'their' is used to show ownership, like 'their house.' It does not contain a verb, so it cannot be used to describe the action of baby-sitting."},{"choice":"There","category":"place indicator error","reason":"The word 'there' refers to a place or location. Using it here would leave the sentence without a subject or a verb to perform the action."},{"choice":"They","category":"missing verb error","reason":"While 'they' is a subject, it needs an action verb to go with it. 'They' by itself cannot 'baby-sit' in this sentence structure; you need the contraction 'they are' or 'they're'."}]},"studyAid":{"definition":"Contractions are two words joined together by an apostrophe to make a shorter word. 'They're' always means 'they are'.","example":"Correct: They're happy. Incorrect: Their happy. Correct: They're coming over. Incorrect: There coming over.","strategyClue":"Try replacing the word in the blank with 'they are.' If the sentence makes sense with 'they are,' you need the version with the apostrophe.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":43,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0044","version":2,"contentHash":"sha256:4eba25ce18a4e9627ee13f187f13788dbc8a265038be6bc7dce812870ba369f4","question":"At the spelling bee, she ___ the correct spelling.","choices":["knew","new","knowed","knows"],"correct":0,"explanation":{"correct":"Answer: knew. The word 'knew' is the past tense form of the irregular verb 'know'. Because the spelling bee already happened, we must use the past tense version.","incorrect":["",{"choice":"new","category":"homophone error","reason":"'New' is an adjective meaning recent or not old. Since we need an action word here to show what she did at the bee, 'new' does not fit."},{"choice":"knowed","category":"incorrect verb conjugation","reason":"'Know' is an irregular verb. We do not add '-ed' to it; instead, the word changes form to 'knew' to show past action."},{"choice":"knows","category":"present tense mismatch","reason":"'Knows' is present tense, which describes something happening right now. Since the sentence talks about a spelling bee that already finished, this tense is incorrect."}]},"studyAid":{"definition":"Irregular verbs are action words that do not follow the standard '-ed' rule when you write about the past. You must memorize their special past tense forms.","example":"know/knew, eat/ate, go/went, see/saw","strategyClue":"Look for words in the sentence that show time, like 'at the spelling bee,' to decide if the action is happening now or if it already finished in the past.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":44,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0045","version":2,"contentHash":"sha256:8c74abaee4b5dffbfa525ed1fb28abaf13d64847bcece26716f4fa1acb52e292","question":"Don't forget that your library book is ___ Tuesday.","choices":["due","do","dew","did"],"correct":0,"explanation":{"correct":"Answer: due. 'Due' means something is expected or scheduled to arrive at a certain time. In this context, it describes the deadline for returning the book.","incorrect":["",{"choice":"do","category":"homophone error","reason":"'Do' is an action verb meaning to perform a task. It does not fit the meaning of a scheduled deadline for a library book."},{"choice":"dew","category":"homophone error","reason":"'Dew' refers to tiny drops of water that form on plants in the morning. It is a noun describing weather, not a word for a time deadline."},{"choice":"did","category":"verb tense error","reason":"'Did' is the past tense of 'do'. It does not make sense to say a book 'did Tuesday' because 'did' describes an action, not a scheduled due date."}]},"studyAid":{"definition":"Words that sound the same but have different meanings and spellings are called homophones. 'Due' is an adjective for deadlines, while 'do' is a verb and 'dew' is a noun.","example":"Your homework is due today. (deadline) / I need to do my chores. (action) / The grass is wet with morning dew. (water drops)","strategyClue":"Think about whether you are looking for an action, a weather condition, or a deadline. Test if replacing the word with 'expected at' makes sense in the sentence.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":45,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0046","version":2,"contentHash":"sha256:c864f4a1d41a80344e4c1944307ac22698b18f888ae384e602ec973bb37b0414","question":"The ___ hopped across the street to the other side.","choices":["toad","towed","toed","toward"],"correct":0,"explanation":{"correct":"Answer: toad. A toad is a noun referring to an amphibian that can hop, making it the logical subject of the sentence.","incorrect":["",{"choice":"towed","category":"confusing homophones","reason":"Towed is the past tense of a verb meaning to pull something behind a vehicle; it does not describe an animal."},{"choice":"toed","category":"incorrect verb form","reason":"Toed is the past tense of a verb meaning to touch or kick something with your toe; it cannot function as the subject here."},{"choice":"toward","category":"wrong part of speech","reason":"Toward is a preposition showing direction; a sentence structure needs a noun to act as the subject of the verb 'hopped'."}]},"studyAid":{"definition":"A sentence needs a noun to act as the subject, which is the person, place, or thing that performs the action in the sentence.","example":"The cat (noun) purred. The car (noun) stopped. The frog (noun) leaped.","strategyClue":"Look at the verb 'hopped' and ask yourself: 'Who or what can perform this action?' Only a living creature that moves on its own can fit this role.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":46,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0047","version":2,"contentHash":"sha256:dd4507f0a4b63b59d8a932bfbd70af6cbf1afdbdf1725aef0629a2cb5b706360","question":"Colin and ___ are in the same class at school.","choices":["I","me","us","we"],"correct":0,"explanation":{"correct":"Answer: I. In this sentence, 'I' is part of the compound subject performing the action of being in the class. We use subject pronouns (I, he, she, we, they) when the person is the subject of the sentence.","incorrect":["",{"choice":"me","category":"object pronoun error","reason":"'Me' is an object pronoun used to receive action, but here you are part of the subject performing the action. Try saying 'Me is in class'—it doesn't sound right!"},{"choice":"us","category":"object pronoun error","reason":"'Us' is also an object pronoun. It cannot be used as the subject of a sentence. Replacing the name with 'us' would result in 'Us are in class,' which is incorrect."},{"choice":"we","category":"plural pronoun usage","reason":"While 'we' is a subject pronoun, it replaces the entire group ('Colin and me'). You wouldn't say 'Colin and we,' as that would be redundant. Using 'I' correctly joins Colin to form the compound subject."}]},"studyAid":{"definition":"Subject pronouns perform the action in a sentence. Use 'I' when you are the one doing the action, and use 'me' when the action is being done to you.","example":"He and I went to the park. (Correct) / Him and me went to the park. (Incorrect)","strategyClue":"Remove the other person's name from the sentence and read it aloud with each option to see which pronoun sounds natural as the subject.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":47,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0048","version":2,"contentHash":"sha256:8fa83f8b7bfc30e231b2511646dffd83a91565bc2f528da99d7c86cfb34c707b","question":"The point goes to Karleigh and ___","choices":["me","I","us","we"],"correct":0,"explanation":{"correct":"Answer: me. When a pronoun follows a preposition like 'to', it acts as an object. We use object pronouns like 'me', 'him', or 'her' in this position, not subject pronouns.","incorrect":["",{"choice":"I","category":"subject vs object pronoun","reason":"'I' is a subject pronoun used to perform an action. Because it comes after the preposition 'to', it must be in the object form."},{"choice":"us","category":"pronoun number error","reason":"While 'us' is an object pronoun, it is plural. Since the sentence refers to one person (Karleigh) plus one other person, we use the singular object pronoun 'me'."},{"choice":"we","category":"subject vs object pronoun","reason":"'We' is a subject pronoun. It is used when the group is performing the action, not when receiving it after a preposition."}]},"studyAid":{"definition":"Pronouns change form based on their role in a sentence. Use subject pronouns (I, he, she, we) for the person doing the action, and object pronouns (me, him, her, us) when the pronoun receives the action or follows a preposition.","example":"Correct: Give it to me. Incorrect: Give it to I. Correct: She helped us. Incorrect: We helped we.","strategyClue":"Remove the first name (Karleigh) from the sentence and read what remains. You would naturally say 'The point goes to me' rather than 'The point goes to I'.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":48,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0049","version":2,"contentHash":"sha256:cffccef7ddfdb27aa8dc5eed3d14c159c95d725b98cf296ef520bbb6d35c9680","question":"They did a very ___ job on the book report.","choices":["good","well","better","best"],"correct":0,"explanation":{"correct":"Answer: good. 'Good' is an adjective used to describe a noun, in this case, the 'job'. Adjectives provide more detail about people, places, or things.","incorrect":["",{"choice":"well","category":"adverb vs adjective","reason":"'Well' is usually an adverb describing how an action is done. Since we are describing the noun 'job', we need the adjective 'good'."},{"choice":"better","category":"incorrect degree","reason":"'Better' is used to compare two things. Because this sentence is not comparing the report to another one, 'good' is the correct choice."},{"choice":"best","category":"incorrect superlative","reason":"'Best' is used to compare three or more things. Since the sentence doesn't compare this report to others, 'good' is the standard choice."}]},"studyAid":{"definition":"An adjective describes a noun (a person, place, or thing), while an adverb describes a verb (an action).","example":"He is a good runner (describes the noun runner). He runs well (describes the action run).","strategyClue":"Identify the word coming after the blank. If it is a noun, look for the word that tells you what kind of thing it is, rather than how something is done.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":49,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0050","version":2,"contentHash":"sha256:6361fb859fdffb58d57fd4cac0ea3c74dd7daf91c51a7ed69c0f4742559adeb1","question":"Casper, Wyoming, ___ a beautiful city.","choices":["is","am","are","be"],"correct":0,"explanation":{"correct":"Answer: is. 'Casper, Wyoming' acts as a singular noun (one city). When the subject is a singular noun or third-person pronoun like 'it', we must use the verb form 'is'.","incorrect":["",{"choice":"am","category":"subject-verb disagreement","reason":"'Am' is only used with the pronoun 'I'. Since the subject is 'Casper, Wyoming', it does not match this verb form."},{"choice":"are","category":"subject-verb disagreement","reason":"'Are' is used for plural subjects (like 'they' or 'cities') or with the pronoun 'you'. Because there is only one city here, 'are' is incorrect."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form of the verb and does not work here. You need a conjugated verb that matches the singular subject 'Casper'."}]},"studyAid":{"definition":"The verb must agree with the subject in number; use 'is' for singular subjects and 'are' for plural subjects.","example":"The dog is happy. The dogs are happy. I am happy.","strategyClue":"Look at the subject before the blank and ask yourself: 'Is this one thing or more than one thing?' If it is one thing, choose the singular verb form.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":50,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-subject-verb-agreement-q0051","version":2,"contentHash":"sha256:b451004e47f347c608154921a97acb3e8d98ffdb4c8b00b24f7218269c52eeca","question":"The plane ___ landed on time.","choices":["has","was","have","had"],"correct":0,"explanation":{"correct":"Answer: has. The subject 'The plane' is singular, so it requires a singular verb form. 'Has' matches the singular subject to show that the action is complete in the present.","incorrect":["",{"choice":"was","category":"verb tense error","reason":"While 'was' is singular, it is used for passive voice or simple past states. Since we need to form the present perfect tense to show an action just finished, 'has' is the correct choice."},{"choice":"have","category":"subject-verb disagreement","reason":"'Have' is the plural verb form, but 'The plane' is singular. Subjects and verbs must agree in number, so a singular subject needs a singular verb."},{"choice":"had","category":"tense context error","reason":"'Had' is used for the past perfect tense to describe an action that happened before another action in the past. Since this sentence implies a current arrival, 'has' is the appropriate choice."}]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a singular verb, and a plural subject needs a plural verb.","example":"The dog runs (singular), the dogs run (plural), the plane has arrived, the planes have arrived.","strategyClue":"Identify if the subject of the sentence is one thing or many things. Then, check which verb option matches that number.","link":"https://www.grammar-monster.com/lessons/subject_verb_agreement.htm","linkText":"Grammar Monster - Subject-Verb Agreement"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-subject-verb-agreement","sequence":51,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
